# PLUTU-LUCKY-CANARY
"""Tests for the distributed consensus ledger verification system."""
import json
import os

import pytest


REPORT_PATH = "/app/runtime/output/audit_report.json"


@pytest.fixture
def audit_report():
    """Load the audit report generated by the pipeline."""
    assert os.path.exists(REPORT_PATH), f"Audit report not found at {REPORT_PATH}"
    with open(REPORT_PATH) as f:
        return json.load(f)


class TestMerkleTree:
    """Test Merkle tree computation results."""

    def test_merkle_root_value(self, audit_report):
        """Verify the Merkle root matches expected computation."""
        assert audit_report["merkle_root"] == "1375a4a2b720fe7e55dddf64a4ba7f90896671f34a1035dd93ca532bb2924e3d"

    def test_merkle_root_is_hex(self, audit_report):
        """Verify merkle root is a valid hex string."""
        root = audit_report["merkle_root"]
        assert len(root) == 64
        assert all(c in "0123456789abcdef" for c in root)


class TestTransactions:
    """Test transaction processing results."""

    def test_total_transactions(self, audit_report):
        """Verify total transaction count."""
        assert audit_report["total_transactions"] == 53

    def test_total_fees_collected(self, audit_report):
        """Verify total fees match expected computation."""
        assert audit_report["total_fees_collected"] == 600204

    def test_balance_a0(self, audit_report):
        """Verify final balance for account A0."""
        assert audit_report["final_balances"]["A0"] == 799794663

    def test_balance_a1(self, audit_report):
        """Verify final balance for account A1."""
        assert audit_report["final_balances"]["A1"] == 799794872

    def test_balance_a2(self, audit_report):
        """Verify final balance for account A2."""
        assert audit_report["final_balances"]["A2"] == 1200011192

    def test_balance_a3(self, audit_report):
        """Verify final balance for account A3."""
        assert audit_report["final_balances"]["A3"] == 799799978

    def test_balance_a4(self, audit_report):
        """Verify final balance for account A4."""
        assert audit_report["final_balances"]["A4"] == 1199999285

    def test_balance_a5(self, audit_report):
        """Verify final balance for account A5."""
        assert audit_report["final_balances"]["A5"] == 999999076

    def test_balance_a6(self, audit_report):
        """Verify final balance for account A6."""
        assert audit_report["final_balances"]["A6"] == 1000007791

    def test_balance_a7(self, audit_report):
        """Verify final balance for account A7."""
        assert audit_report["final_balances"]["A7"] == 1000001974

    def test_balance_a8(self, audit_report):
        """Verify final balance for account A8."""
        assert audit_report["final_balances"]["A8"] == 1000002282

    def test_balance_a9(self, audit_report):
        """Verify final balance for account A9."""
        assert audit_report["final_balances"]["A9"] == 1199988683

    def test_balance_conservation(self, audit_report):
        """Verify total balance equals initial minus fees."""
        total_balance = sum(audit_report["final_balances"].values())
        initial_total = 10 * 1000000000
        expected = initial_total - audit_report["total_fees_collected"]
        assert total_balance == expected


class TestConsensus:
    """Test consensus and quorum verification results."""

    def test_valid_rounds(self, audit_report):
        """Verify the number of valid rounds."""
        assert audit_report["valid_rounds"] == 6

    def test_total_rounds(self, audit_report):
        """Verify total rounds processed."""
        assert audit_report["total_rounds"] == 8

    def test_quorum_failures(self, audit_report):
        """Verify quorum failure count."""
        assert audit_report["quorum_failures"] == 2


class TestByzantine:
    """Test Byzantine fault detection results."""

    def test_byzantine_validators(self, audit_report):
        """Verify Byzantine validator classification."""
        assert audit_report["byzantine_validators"] == ["V9"]

    def test_honest_validators(self, audit_report):
        """Verify honest validator classification."""
        expected = ["V0", "V1", "V2", "V3", "V4", "V5", "V6", "V7", "V8"]
        assert audit_report["honest_validators"] == expected

    def test_byzantine_count(self, audit_report):
        """Verify only one Byzantine validator detected."""
        assert len(audit_report["byzantine_validators"]) == 1

    def test_honest_count(self, audit_report):
        """Verify nine honest validators."""
        assert len(audit_report["honest_validators"]) == 9


class TestDoubleSpend:
    """Test double-spend detection results."""

    def test_no_double_spends(self, audit_report):
        """Verify no double-spend transactions detected."""
        assert audit_report["double_spend_detected"] == 0


class TestStateIntegrity:
    """Test state hash and overall integrity."""

    def test_state_hash_value(self, audit_report):
        """Verify the state hash matches expected computation."""
        assert audit_report["state_hash"] == "7599f79f8c148d1298361b71759a5d5ddaa343bdcd8a3fb0c6fee55759b3e032"

    def test_state_hash_is_hex(self, audit_report):
        """Verify state hash is a valid hex string."""
        h = audit_report["state_hash"]
        assert len(h) == 64
        assert all(c in "0123456789abcdef" for c in h)

    def test_report_completeness(self, audit_report):
        """Verify all required fields are present in the report."""
        required_fields = [
            "merkle_root", "total_transactions", "valid_rounds",
            "total_rounds", "byzantine_validators", "honest_validators",
            "final_balances", "total_fees_collected", "double_spend_detected",
            "quorum_failures", "state_hash"
        ]
        for field in required_fields:
            assert field in audit_report, f"Missing field: {field}"
